(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-964":{scenario:{company:"Lumora Building Energy",supervisor:{name:"Tạ Quang Vĩnh",role:{vi:"Trưởng nhóm Kiểm toán Năng lượng",en:"Energy Audit Lead"}},ref_code:"MV-6412",title:{vi:"Nền đúng thời tiết. Tiết kiệm đúng số đo.",en:"Weather-true baseline. Metered savings."},brief:{vi:"Bạn kiểm tra báo cáo đo lường và kiểm chứng (M&V) MV-6412 cho giải pháp ECM-07: lắp biến tần và tối ưu điều khiển cụm chiller của một tòa văn phòng. Công tơ riêng đo liên tục toàn bộ cụm chiller; tiết kiệm dự kiến chỉ khoảng 6% điện toàn tòa. Mô hình nền: E = 42000 + 180 x CDD (kWh/tháng). Tháng 10: CDD = 260, điện cụm chiller đo được 71500 kWh. Sửa phương án IPMVP và số kWh tiết kiệm trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are reviewing measurement and verification (M&V) report MV-6412 for ECM-07: variable speed drives and optimized controls on an office tower chiller plant. A dedicated meter continuously logs the whole chiller plant; expected savings are only about 6% of building electricity. Baseline model: E = 42000 + 180 x CDD (kWh/month). October: CDD = 260, metered chiller plant use 71500 kWh. Correct the IPMVP option and the kWh savings in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Kế hoạch M&V đã phê duyệt · MV-6412",en:"Approved M&V plan · MV-6412"},fields:[{id:"MV_OPTION",label:{vi:"Phương án M&V theo IPMVP",en:"IPMVP M&V option"},initial:"IPMVP-C",expected:"IPMVP-B",choices:["IPMVP-A","IPMVP-B","IPMVP-C"],reference:"Kế hoạch M&V đã phê duyệt",hint:{vi:"Ranh giới đo bao trùm cụm chiller và mọi thông số được đo liên tục; tiết kiệm nhỏ so với công tơ tổng thì khó tách bằng phương án toàn tòa.",en:"The boundary covers the chiller plant with every parameter metered continuously; small savings are hard to isolate on the whole-building meter."}},{id:"SAVED_KWH",label:{vi:"Điện năng tiết kiệm tháng 10 (kWh)",en:"October energy savings (kWh)"},initial:"10500",expected:"17300",reference:"Bảng tính tiết kiệm M&V",ref_value:{vi:"Nền E = 42000 + 180 x CDD; CDD tháng 10 = 260; đo được 71500 kWh",en:"Baseline E = 42000 + 180 x CDD; October CDD = 260; metered 71500 kWh"},hint:{vi:"So sánh với nền đã hiệu chỉnh theo thời tiết của chính kỳ báo cáo, không so với số đo thô của năm trước.",en:"Compare with the weather-adjusted baseline of the reporting period itself, not with last year's raw reading."}}],sop32:{vi:"Tiết kiệm (kWh) = nền hiệu chỉnh - tiêu thụ đo được của kỳ báo cáo; nền hiệu chỉnh = 42000 + 180 x CDD của chính kỳ báo cáo (điều chỉnh thường xuyên theo IPMVP).",en:"Savings (kWh) = adjusted baseline - metered use in the reporting period; adjusted baseline = 42000 + 180 x CDD of that same period (IPMVP routine adjustment)."},context:{label:"EMS / MV-6412",metrics:[{label:{vi:"CDD tháng 10",en:"October CDD"},value:"260"},{label:{vi:"Điện cụm chiller đo được",en:"Metered chiller plant use"},value:"71,500 kWh"},{label:{vi:"Mô hình nền (kWh/tháng)",en:"Baseline model (kWh/month)"},value:"42000 + 180 x CDD"}]},crisis:{vi:"Đại diện ESCO nhắn: “Hợp đồng cam kết tiết kiệm 25%, cứ lấy tháng nóng nhất năm ngoái làm nền và ghi phương án C cho gọn, chủ đầu tư không soi đâu. Cần ký nghiệm thu để thanh toán đợt 2 trong tuần này.”",en:"The ESCO representative messages you: “The contract promises 25% savings, just use last year's hottest month as the baseline and write Option C to keep it simple, the owner will not check. We need sign-off for the second payment this week.”"},options:{safe:{vi:"Giữ phương án IPMVP-B, tính tiết kiệm trên nền hiệu chỉnh theo CDD, nêu rõ độ bất định và báo trưởng nhóm; đề xuất họp ba bên rà soát cam kết hợp đồng bằng số liệu đo.",en:"Keep IPMVP-B, compute savings on the CDD-adjusted baseline, state the uncertainty and inform the lead; propose a three-party review of the contract commitment using metered data."},shortcut:{vi:"Lấy tháng nóng nhất năm ngoái làm nền để đạt 25% và ký nghiệm thu cho kịp đợt thanh toán.",en:"Use last year's hottest month as the baseline to reach 25% and sign off in time for the payment."},wait:{vi:"Gác báo cáo lại, chờ ESCO và chủ đầu tư tự thống nhất con số tiết kiệm.",en:"Shelve the report and wait for the ESCO and the owner to agree on a savings figure."}},questions:{vi:["Vì sao chọn IPMVP-B thay vì IPMVP-C? Dữ liệu công tơ nào chứng minh lựa chọn của bạn?","Trình bày cách hiệu chỉnh nền theo CDD và rủi ro nếu so sánh với số đo thô của năm trước hoặc chọn kỳ nền có lợi."],en:["Why did you choose IPMVP-B instead of IPMVP-C? Which meter data supports your choice?","Explain how you adjusted the baseline for CDD and the risk of comparing with last year's raw reading or cherry-picking the baseline period."]},hints:{vi:["Chạy lệnh liệt kê công tơ để xác định ranh giới đo trước khi chọn phương án IPMVP.","Thay CDD của kỳ báo cáo vào mô hình nền ở SOP mục 3.2 rồi mới trừ số đo thực tế.","Đọc lại SOP mục 4.2: không chọn kỳ nền hay phương án đo để làm đẹp kết quả; báo cáo áp lực bằng văn bản."],en:["List the meters to confirm the measurement boundary before choosing the IPMVP option.","Plug the reporting-period CDD into the baseline model in SOP 3.2 before subtracting the metered use.","Re-read SOP 4.2: never pick a baseline period or M&V option to flatter results; report pressure in writing."]},terminal:{system:"ems-mv",settable:["MV_OPTION","SAVED_KWH"],commands:[{cmd:"meter list",out:{vi:"M-CH01: công tơ riêng cụm chiller (máy làm lạnh, bơm, tháp giải nhiệt), ghi liên tục chu kỳ 15 phút. M-MAIN: công tơ tổng tòa nhà.",en:"M-CH01: dedicated chiller plant meter (chillers, pumps, cooling towers), continuous 15-minute logging. M-MAIN: building main meter."}},{cmd:"cat baseline.txt",out:{vi:"Mô hình nền 12 tháng năm 2025: E = 42000 + 180 x CDD (kWh/tháng), R2 = 0.93, CV(RMSE) = 8.1%.",en:"12-month 2025 baseline model: E = 42000 + 180 x CDD (kWh/month), R2 = 0.93, CV(RMSE) = 8.1%."}},{cmd:"trend m-ch01 2026-10",out:{vi:"Tháng 10/2026: điện cụm chiller đo được 71500 kWh. Tháng 10/2025: 82000 kWh.",en:"October 2026: metered chiller plant use 71500 kWh. October 2025: 82000 kWh."}},{cmd:"weather cdd",out:{vi:"CDD nhiệt độ gốc 18°C: tháng 10/2025 = 228, tháng 10/2026 = 260 (trạm khí tượng gần nhất).",en:"CDD at 18°C base: October 2025 = 228, October 2026 = 260 (nearest weather station)."}}]}},learning:{summary:{vi:"Kỹ sư hiệu quả năng lượng tòa nhà kiểm toán năng lượng, mô phỏng và đề xuất giải pháp tiết kiệm (ECM) cho điều hòa thông gió, chiếu sáng, bơm và vỏ công trình, rồi đo lường và kiểm chứng (M&V) mức tiết kiệm thực tế. Công việc đòi hỏi vững nhiệt lạnh, điện, dữ liệu BMS, quy chuẩn công trình sử dụng năng lượng hiệu quả và trung thực tuyệt đối với số liệu đo.",en:"A building energy efficiency engineer audits energy use, models and proposes energy conservation measures (ECM) for HVAC, lighting, pumps and the building envelope, then measures and verifies (M&V) the actual savings. The role requires strong HVAC, electrical and BMS data skills, knowledge of energy-efficient building codes and strict honesty with metered data."},responsibilities:{vi:["Thực hiện kiểm toán năng lượng: thu thập hóa đơn, đo đạc hiện trường và lập cân bằng năng lượng theo hệ thống.","Xây dựng đường cơ sở năng lượng và chỉ số hiệu suất (EnPI) có hiệu chỉnh theo thời tiết và mức sử dụng.","Đề xuất và tính hiệu quả kinh tế các giải pháp ECM: chiller, biến tần, LED, điều khiển BMS, vỏ bao che.","Lập kế hoạch M&V, chọn phương án IPMVP, giám sát lắp công tơ và tính tiết kiệm định kỳ.","Hỗ trợ tuân thủ QCVN 09:2017/BXD, báo cáo năng lượng định kỳ và hệ thống quản lý năng lượng ISO 50001."],en:["Run energy audits: collect bills, take field measurements and build a system-level energy balance.","Build energy baselines and performance indicators (EnPI) adjusted for weather and occupancy.","Propose ECMs and assess their economics: chillers, drives, LED, BMS controls and envelope upgrades.","Write M&V plans, choose the IPMVP option, supervise meter installation and calculate periodic savings.","Support compliance with QCVN 09:2017/BXD, periodic energy reporting and an ISO 50001 energy management system."]},competencies:[{name:{vi:"Kiểm toán năng lượng",en:"Energy auditing"},desc:{vi:"Đo đạc, phân tách tiêu thụ theo hệ thống và tìm cơ hội tiết kiệm có căn cứ số liệu.",en:"Measure, break down consumption by system and find data-backed savings opportunities."}},{name:{vi:"Mô hình hóa & thống kê",en:"Modeling & statistics"},desc:{vi:"Lập hồi quy theo CDD, đánh giá R2, CV(RMSE) và mô phỏng năng lượng tòa nhà.",en:"Build CDD regressions, assess R2 and CV(RMSE) and run building energy simulations."}},{name:{vi:"HVAC & điều khiển",en:"HVAC & controls"},desc:{vi:"Hiểu cụm chiller, bơm, tháp giải nhiệt, AHU và chiến lược điều khiển trên BMS.",en:"Understand chiller plants, pumps, cooling towers, AHUs and BMS control strategies."}},{name:{vi:"Phân tích kinh tế",en:"Economic analysis"},desc:{vi:"Tính thời gian hoàn vốn, NPV, chi phí vòng đời và rủi ro của từng giải pháp.",en:"Calculate payback, NPV, life-cycle cost and risk for each measure."}},{name:{vi:"Liêm chính số liệu",en:"Data integrity"},desc:{vi:"Không chọn kỳ nền hay phương pháp để làm đẹp kết quả; công bố độ bất định.",en:"Never cherry-pick baselines or methods to flatter results; disclose uncertainty."}}],knowledge:{vi:["Luật Sử dụng năng lượng tiết kiệm và hiệu quả số 50/2010/QH12 và các văn bản sửa đổi, hướng dẫn.","QCVN 09:2017/BXD về các công trình xây dựng sử dụng năng lượng hiệu quả: vỏ công trình, HVAC, chiếu sáng.","IPMVP: bốn phương án A, B, C, D, ranh giới đo, điều chỉnh thường xuyên và không thường xuyên.","ISO 50001 (hệ thống quản lý năng lượng), ISO 50002 (kiểm toán năng lượng) và ISO 50006 (đường cơ sở, EnPI).","ASHRAE 90.1 và ASHRAE Guideline 14 về đo lường tiết kiệm và tiêu chí đánh giá mô hình."],en:["Law on Economical and Efficient Use of Energy No. 50/2010/QH12 and its amendments and guidance.","QCVN 09:2017/BXD on energy-efficient buildings: envelope, HVAC and lighting.","IPMVP: options A, B, C and D, measurement boundary, routine and non-routine adjustments.","ISO 50001 (energy management systems), ISO 50002 (energy audits) and ISO 50006 (baselines, EnPI).","ASHRAE 90.1 and ASHRAE Guideline 14 on savings measurement and model acceptance criteria."]},tools:["Hệ thống quản lý tòa nhà (BMS)","Phần mềm mô phỏng năng lượng (EnergyPlus)","Công tơ và bộ ghi dữ liệu di động","Camera nhiệt","Đồng hồ đo lưu lượng siêu âm","Bảng tính hồi quy"],kpis:{vi:["Điện năng tiết kiệm đã kiểm chứng so với cam kết (kWh/năm).","Cường độ sử dụng năng lượng EUI (kWh/m2/năm) của tòa nhà.","Mô hình nền đạt tiêu chí thống kê (R2, CV(RMSE)) đã thống nhất.","Thời gian hoàn vốn thực tế so với dự kiến của các ECM."],en:["Verified energy savings versus commitment (kWh/year).","Building energy use intensity EUI (kWh/m2/year).","Baseline models meeting the agreed statistical criteria (R2, CV(RMSE)).","Actual versus planned payback of the ECMs."]},day:[{time:"08:00",vi:"Xem cảnh báo EMS, so sánh tải chiller đêm qua với ngày có thời tiết tương đương.",en:"Check EMS alarms and compare last night's chiller load with a weather-matched day."},{time:"09:30",vi:"Đo hiện trường: công suất bơm, nhiệt độ nước lạnh vào ra, lưu lượng siêu âm.",en:"Field measurements: pump power, chilled water supply and return temperatures, ultrasonic flow."},{time:"13:30",vi:"Cập nhật mô hình hồi quy nền và tính tiết kiệm tháng theo kế hoạch M&V.",en:"Update the baseline regression and calculate monthly savings per the M&V plan."},{time:"15:30",vi:"Họp với ESCO và ban quản lý tòa nhà về kết quả và điều chỉnh không thường xuyên.",en:"Meet the ESCO and facility team on results and non-routine adjustments."},{time:"17:00",vi:"Hoàn thiện báo cáo M&V, lưu dữ liệu thô và nhật ký giả định.",en:"Finish the M&V report and archive raw data and the assumptions log."}],mistakes:{vi:["So sánh với số đo cùng kỳ năm trước mà không hiệu chỉnh theo thời tiết và mức sử dụng.","Chọn phương án C khi tiết kiệm nhỏ hơn mức dao động tự nhiên của công tơ tổng.","Nhầm kW/RT với COP hoặc tính hoàn vốn trên công suất danh định thay vì vận hành thực tế."],en:["Comparing with last year's reading without adjusting for weather and occupancy.","Choosing Option C when savings are smaller than the natural noise of the main meter.","Confusing kW/RT with COP or computing payback on nameplate power instead of actual operation."]},career:[{vi:"Kỹ thuật viên đo đạc năng lượng",en:"Energy metering technician"},{vi:"Kỹ sư kiểm toán năng lượng",en:"Energy audit engineer"},{vi:"Chuyên gia M&V và quản lý năng lượng",en:"M&V and energy management specialist"},{vi:"Giám đốc dịch vụ năng lượng (ESCO) / phát triển bền vững",en:"ESCO director / head of sustainability"}],glossary:[{term:"ECM",vi:"Giải pháp tiết kiệm năng lượng cụ thể, ví dụ lắp biến tần hay thay chiller hiệu suất cao.",en:"A specific energy conservation measure, such as adding drives or replacing a chiller."},{term:"IPMVP",vi:"Nghị định thư quốc tế về đo lường và kiểm chứng hiệu quả, gồm các phương án A, B, C, D.",en:"International protocol for measuring and verifying performance, with options A, B, C and D."},{term:"CDD",vi:"Độ ngày làm lạnh: tổng phần nhiệt độ trung bình ngày vượt nhiệt độ gốc, đo nhu cầu làm lạnh.",en:"Cooling degree days: the sum of daily mean temperature above a base, a proxy for cooling demand."},{term:"EUI",vi:"Cường độ sử dụng năng lượng, tính bằng kWh trên mét vuông sàn mỗi năm.",en:"Energy use intensity, measured in kWh per square meter of floor area per year."},{term:"kW/RT",vi:"Điện năng tiêu thụ trên mỗi tấn lạnh; càng thấp thì cụm chiller càng hiệu quả.",en:"Electrical input per ton of refrigeration; the lower it is, the more efficient the plant."}],quiz:[{q:{vi:"Mô hình nền E = 30000 + 150 x CDD; kỳ báo cáo CDD = 200, đo được 52000 kWh. Tiết kiệm là bao nhiêu?",en:"Baseline E = 30000 + 150 x CDD; reporting CDD = 200, metered 52000 kWh. What are the savings?"},options:{vi:["8000 kWh","2000 kWh","60000 kWh","22000 kWh"],en:["8000 kWh","2000 kWh","60000 kWh","22000 kWh"]},answer:0,explain:{vi:"Nền hiệu chỉnh = 30000 + 150 x 200 = 60000 kWh; tiết kiệm = 60000 - 52000 = 8000 kWh.",en:"Adjusted baseline = 30000 + 150 x 200 = 60000 kWh; savings = 60000 - 52000 = 8000 kWh."}},{q:{vi:"Phương án IPMVP nào dựa trên mô phỏng đã hiệu chỉnh với số liệu đo?",en:"Which IPMVP option relies on a calibrated simulation?"},options:{vi:["Phương án A","Phương án B","Phương án C","Phương án D"],en:["Option A","Option B","Option C","Option D"]},answer:3,explain:{vi:"Phương án D dùng mô phỏng hiệu chỉnh khi không có hoặc không đủ số liệu đo nền.",en:"Option D uses calibrated simulation when baseline metering is missing or insufficient."}},{q:{vi:"ESCO đề nghị lấy tháng nóng nhất năm trước làm nền để đạt cam kết tiết kiệm. Bạn làm gì?",en:"The ESCO asks you to use last year's hottest month as the baseline to meet the savings commitment. What do you do?"},options:{vi:["Đồng ý vì hợp đồng đã ký","Chọn tháng mát nhất cho cân bằng","Giữ nền 12 tháng hiệu chỉnh thời tiết, báo cáo áp lực và đề xuất rà soát ba bên","Không báo cáo tháng này"],en:["Agree because the contract is signed","Pick the coolest month to balance it","Keep the 12-month weather-adjusted baseline, report the pressure and propose a three-party review","Skip this month's report"]},answer:2,explain:{vi:"Chọn kỳ nền có lợi là làm sai lệch kết quả M&V; phải giữ phương pháp đã phê duyệt và báo cáo minh bạch.",en:"Cherry-picking the baseline distorts M&V results; keep the approved method and report transparently."}},{q:{vi:"Hai cụm chiller cùng tải: cụm X 0.62 kW/RT, cụm Y 0.78 kW/RT. Nhận định nào đúng?",en:"Two chiller plants at the same load: X at 0.62 kW/RT, Y at 0.78 kW/RT. Which statement is correct?"},options:{vi:["Cụm Y hiệu quả hơn","Cụm X hiệu quả hơn","Hai cụm như nhau","Không so sánh được kW/RT"],en:["Plant Y is more efficient","Plant X is more efficient","They are equal","kW/RT cannot be compared"]},answer:1,explain:{vi:"kW/RT là điện năng trên một tấn lạnh, giá trị thấp hơn nghĩa là hiệu quả cao hơn.",en:"kW/RT is power per ton of cooling; a lower value means higher efficiency."}}],tools_en:["Building management system (BMS)","Energy simulation software (EnergyPlus)","Portable meters and data loggers","Thermal imaging camera","Ultrasonic flow meter","Regression analysis spreadsheet"]}}})})(window.KKR);
